document.querySelectorAll(".filter-tag").forEach(n=>{n.addEventListener("click",()=>{document.querySelectorAll(".filter-tag").forEach(n=>n.classList.remove("active")),n.classList.add("active")})});document.addEventListener("DOMContentLoaded",()=>{const n=document.getElementById("cartBadge");n&&fetch("/Catalog/GetCartCount").then(n=>{if(!n.ok)throw new Error("HTTP "+n.status);return n.json()}).then(t=>{n.textContent=t.count}).catch(n=>console.error("Не удалось получить количество товаров:",n))});